            double num = 0, den = 0;
            for (int i = 0; i < b.N; i++) { double d = Ax[i] - b[i]; num += d * d; den += b[i] * b[i]; }
            return math.sqrt(num) / math.sqrt(math.max(den, (double)1e-30));
        }

